tlsOptions := common.PtrValueOrDefault(options.TLS)
var tlsConfig tls.Config
var err error
if (tlsOptions.Reality == nil || !tlsOptions.Reality.Enabled) &&
	(tlsOptions.Engine == "" || tlsOptions.Engine == "go") &&
	tlsOptions.UTLS != nil && tlsOptions.UTLS.Enabled &&
	(tlsOptions.UTLS.Fingerprint == "" || tlsOptions.UTLS.Fingerprint == "chrome") {
	factory := service.FromContext[interface {
		NewChromeClient(context.Context, string, option.OutboundTLSOptions) (tls.Config, error)
	}](ctx)
	if factory == nil {
		return nil, E.New("Chrome TLS factory is not registered")
	}
	tlsConfig, err = factory.NewChromeClient(ctx, options.Server, tlsOptions)
} else {
	tlsConfig, err = tls.NewClient(ctx, logger, options.Server, tlsOptions)
}
